import math
from collections.abc import Mapping


def validate_rollout_record(record: dict) -> list[str]:
    required = {
        "task_id", "environment_id", "environment_version",
        "token_ids", "policy_mask", "behavior_logprobs",
        "policy_versions", "turn_ids",
        "action_ids", "observations", "rewards", "stop_reason",
        "terminated", "truncated", "infra_error",
    }
    errors: list[str] = []
    missing = sorted(required - set(record))
    if missing:
        return ["missing fields: " + ", ".join(missing)]

    token_ids = record["token_ids"]
    mask = record["policy_mask"]
    turns = record["turn_ids"]
    logprobs = record["behavior_logprobs"]

    if not all(isinstance(item, list) for item in (token_ids, mask, turns, logprobs)):
        return ["token_ids, policy_mask, turn_ids and behavior_logprobs must be lists"]
    if not (len(token_ids) == len(mask) == len(turns)):
        errors.append("token_ids, policy_mask and turn_ids must have equal lengths")
    if not all(x in (0, 1) and not isinstance(x, bool) for x in mask):
        errors.append("policy_mask must contain integer zeros and ones")
    if sum(x == 1 for x in mask) != len(logprobs):
        errors.append("logprob count must equal the number of policy tokens")
    try:
        valid_logprobs = all(math.isfinite(float(x)) and float(x) <= 0.0 for x in logprobs)
    except (TypeError, ValueError):
        valid_logprobs = False
    if not valid_logprobs:
        errors.append("logprobs must be finite and non-positive")

    versions = record["policy_versions"]
    if not isinstance(versions, Mapping):
        errors.append("policy_versions must be a mapping")
    elif len(token_ids) == len(mask) == len(turns):
        policy_turns = {str(t) for t, m in zip(turns, mask, strict=True) if m == 1}
        missing_turns = policy_turns - {str(t) for t in versions}
        if missing_turns:
            errors.append("missing versions for policy turns")

    actions = record["action_ids"]
    observations = record["observations"]
    rewards = record["rewards"]
    if not all(isinstance(item, list) for item in (actions, observations, rewards)):
        errors.append("action_ids, observations and rewards must be lists")
    elif not (len(actions) == len(rewards) and len(observations) == len(actions) + 1):
        errors.append("observations must have one more item than actions and rewards")

    status_count = sum(bool(record[name]) for name in ("terminated", "truncated", "infra_error"))
    if status_count > 1:
        errors.append("at most one terminal status may be true")
    if status_count == 0 and record["stop_reason"] is not None:
        errors.append("stop_reason requires a stopped rollout")
    if status_count == 1 and not isinstance(record["stop_reason"], str):
        errors.append("a stopped rollout must have a string stop_reason")
    return errors
```

