def run_keydoor_episode(
    actions: list[str],
    *,
    key_color: str,
    door_color: str,
    max_steps: int = 6,
) -> dict:
    colors = {"red", "blue"}
    if key_color not in colors or door_color not in colors:
        raise ValueError("unknown color")
    if isinstance(max_steps, bool) or not isinstance(max_steps, int) or max_steps < 1:
        raise ValueError("max_steps must be positive")

    inspected = False
    carrying = None
    opened: set[str] = set()
    invalid = 0
    terminated = False
    success = False
    steps = 0

    for action in actions[:max_steps]:
        steps += 1
        valid = True
        if action == "inspect":
            inspected = True
        elif action in {"pickup_red", "pickup_blue"}:
            color = action.removeprefix("pickup_")
            if not inspected or color != key_color:
                valid = False
            else:
                carrying = color
        elif action in {"open_red", "open_blue"}:
            color = action.removeprefix("open_")
            if carrying != color:
                valid = False
            else:
                opened.add(color)
        elif action == "finish":
            terminated = True
            success = door_color in opened
        else:
            valid = False

        if not valid:
            invalid += 1
        if terminated:
            break

    truncated = not terminated and steps >= max_steps
    return {
        "reward": 1.0 if success else 0.0,
        "success": success,
        "terminated": terminated,
        "truncated": truncated,
        "steps": steps,
        "invalid_actions": invalid,
        "carrying": carrying,
        "opened": sorted(opened),
    }
```

Minimal checks:

```python
assert run_keydoor_episode(
    ["inspect", "pickup_red", "open_red", "finish"],
    key_color="red", door_color="red",
)["success"]

assert run_keydoor_episode(
    ["finish"], key_color="red", door_color="red",
)["terminated"]

assert run_keydoor_episode(
    ["inspect", "pickup_blue", "finish"],
    key_color="red", door_color="red",
)["invalid_actions"] == 1

assert run_keydoor_episode(
    ["inspect"] * 3,
    key_color="blue", door_color="blue", max_steps=3,
)["truncated"]
```
